  "recovered_c": "#include <stdint.h>\n#include <stddef.h>\n#define VERA_ERR 0xFFFFFFFFFFFFFFFF\n\nuint64_t fn_custom_cipher(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n    if (len <= 0) {\n        return VERA_ERR;\n    }\n\n    uint64_t uVar26 = 0xffffffffffffffff;\n    uint8_t local_130[8];\n    uint8_t local_128[264];\n\n    // Initialize local_130\n    for (size_t i = 0; i < 8; ++i) {\n        local_130[i] = (in[3] >> (i * 8)) & 0x3f;\n    }\n\n    // Process the input data\n    for (size_t i = 0; i < 0x100; ++i) {\n        local_128[i] = 0;\n    }\n\n    for (size_t i = 0; i < 0x100; ++i) {\n        uint8_t bVar24 = local_130[i % 8];\n        uint64_t uVar25 = (uint)bVar24 + (uint)uVar26 & 0xff;\n        uVar26 = uVar25;\n        out[i] = local_128[uVar26];\n        local_128[uVar26] = bVar24;\n    }\n\n    if (len > 0) {\n        uint64_t uVar28 = 0;\n        uint64_t uVar27 = 0;\n        uint64_t uVar29 = len;\n\n        for (size_t i = 0; i < len * 2; ++i) {\n            uVar27 = (uVar27 + 1) & 0xff;\n            uint8_t bVar24 = local_128[uVar27];\n            uVar28 = (uVar28 + bVar24) & 0xff;\n            if (i % (len * 2) == 0 || DAT_00104018 != 0) {\n                uVar28 = ((uVar29 << 7) ^ uVar28) * 0x2d6b + DAT_00104010;\n                uVar28 = uVar28 >> 0xb ^ uVar28;\n            }\n            local_128[uVar27] = local_128[uVar28];\n            local_128[uVar28] = bVar24;\n            out[i] = local_128[(bVar24 + local_128[uVar27]) & 0xff] ^ in[i % len];\n        }\n    }\n\n    return uVar26;\n}"
